import { Component, createMemo, For, mergeProps, Show } from "solid-js";

import { Icon } from "#core/ui-next/components/icon.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { TooltipKeyword } from "#core/ui-next/components/tooltip-keyword.js";
import { Tooltip } from "#core/ui-next/components/tooltip.jsx";
import { spacing } from "#core/ui-next/utilities/spacing.js";

import {
	getDistrictHealthInfo,
	getFeatureInfo,
	PlotTooltipConstructibleInfo,
	PlotTooltipEffectInfo,
	UnitInfoSectionProps,
} from "#base/ui-next/tooltips/plot-tooltip/helpers.js";

import { TicketRow, TicketSection, TicketSectionVariant } from "./utility.jsx";

type PlotDistrictHealthInfo = NonNullable<ReturnType<typeof getDistrictHealthInfo>>;
type IconSizeClass = `size-${spacing}`;

const PlotAlertIcon: Component<{ icon?: string; iconSizeClass?: IconSizeClass }> = (props) => {
	const mergedProps = mergeProps({ iconSizeClass: "size-6" }, props);
	return (
		<div
			class={`${mergedProps.iconSizeClass} shrink-0 bg-contain bg-center bg-no-repeat`}
			style={{ "background-image": props.icon ?? "url(blp:tooltip_alert_icon)" }}
		/>
	);
};

const PlotAlertTimer: Component<{ turns?: number }> = (props) => (
	<Show when={props.turns != null}>
		<div class="flex flex-col items-center ml-2 shrink-0">
			<div
				class="size-6 bg-contain bg-center bg-no-repeat"
				style={{ "background-image": "url(blp:hud_turn-timer)" }}
			/>
			<span class="font-body text-xs text-accent-2">{props.turns}</span>
		</div>
	</Show>
);

interface PlotAlertData {
	title: string;
	/** The ticket variant for the alert banner. @default "negative" */
	variant?: TicketSectionVariant;
	/** Custom icon URL for the alert banner. */
	icon?: string;
	/** Optional custom class for icons size - useful if asset size doesn't match the default icon's size */
	iconSizeClass?: IconSizeClass;
	/** Number of turns remaining on the alert. If not present, the timer is hidden. */
	turns?: number;
	/** Tooltip body shown when the alert label is hovered or focused. */
	tooltipText?: string;
}

interface PlotDistrictHealthAlertData {
	title: string;
	currentHealth: number;
	maxHealth: number;
}

const PlotAlertLabel: Component<{
	alert: PlotAlertData;
	class: string;
	keywordClass?: string;
}> = (props) => (
	<Show
		when={props.alert.tooltipText}
		fallback={
			<L10n.Stylize
				class={props.class}
				text={props.alert.title}
			/>
		}
	>
		{(tooltipText) => (
			<Tooltip.Text text={tooltipText()}>
				<TooltipKeyword class={props.keywordClass}>
					<L10n.Stylize
						class={props.class}
						text={props.alert.title}
					/>
				</TooltipKeyword>
			</Tooltip.Text>
		)}
	</Show>
);

function pushUniqueAlert(target: PlotAlertData[], alert: PlotAlertData): void {
	const hasMatch = target.some(
		(existing) =>
			existing.title === alert.title &&
			existing.turns === alert.turns &&
			existing.variant === alert.variant &&
			existing.icon === alert.icon &&
			existing.tooltipText === alert.tooltipText,
	);

	if (!hasMatch) {
		target.push(alert);
	}
}

/** Looks up the keyword tooltip text for a random-event class from `GameInfo.RandomEventUI`. */
function getEventClassAlertTooltip(eventClass: string): string | undefined {
	return GameInfo.RandomEventUI.lookup(eventClass)?.AlertTooltip ?? undefined;
}

/** Determine if a specific plot effect should generate an alert. */
function getPlotEffectAlert(effect: PlotTooltipEffectInfo): PlotAlertData | null {
	const turns = effect.duration > 0 ? effect.duration : undefined;

	if (effect.plotEffectType === "PLOTEFFECT_RADIOACTIVE_FALLOUT") {
		return {
			title: effect.name,
			tooltipText: "LOC_PEDIA_CONCEPTS_FALLOUT_TOOLTIP",
			turns,
		};
	}

	if (effect.plotEffectType === "PLOTEFFECT_IS_BURNING") {
		return { title: effect.name, turns };
	}

	if (effect.plotEffectType === "PLOTEFFECT_PLAGUE") {
		return {
			title: effect.name,
			tooltipText: "LOC_PEDIA_CONCEPTS_INFECTED_TOOLTIP",
			icon: "url(blp:yield_plague)",
			iconSizeClass: "size-12",
			turns,
		};
	}

	return null;
}

function getStormAlert(storm: RandomEventDefinition): PlotAlertData {
	return {
		title: storm.Name,
		tooltipText: getEventClassAlertTooltip(storm.EventClass),
	};
}

/**
 * Find the volcano random event definition that best matches an active volcano on a plot.
 *
 * Named natural-wonder volcanoes (e.g. Mount Fuji-style entries with `NaturalWonder` set) are
 * matched by feature type. Generic volcanoes are matched by event class plus eruption severity.
 * Returns `null` when no matching event row exists in `GameInfo.RandomEvents`.
 */
function getVolcanoRandomEvent(
	featureType: FeatureType,
	eruptionInfo?: VolcanoEruptionInfo,
): RandomEventDefinition | null {
	const featureName = GameInfo.Features.lookup(featureType)?.FeatureType;

	if (featureName) {
		const namedEvent = GameInfo.RandomEvents.find(
			(event) => event.EventClass === "CLASS_VOLCANO" && event.NaturalWonder === featureName,
		);
		if (namedEvent) {
			return namedEvent;
		}
	}

	return (
		GameInfo.RandomEvents.find(
			(event) =>
				event.EventClass === "CLASS_VOLCANO" &&
				!event.NaturalWonder &&
				event.Severity === eruptionInfo?.severity,
		) ?? null
	);
}
interface PlotAlertSectionProps {
	plotCoord: float2;
	plotIndex: number;
	feature: ReturnType<typeof getFeatureInfo>;
	plotEffects: PlotTooltipEffectInfo[];
	constructibles: PlotTooltipConstructibleInfo[];
	unitEntries: UnitInfoSectionProps[];
}

/** Alert/notification banner displayed near the top of the tooltip. */
export const PlotAlertSection: Component<PlotAlertSectionProps> = (props) => {
	const districtHealth = createMemo(() => getDistrictHealthInfo(props.plotCoord));
	const isOccupiedByEnemy = createMemo(() =>
		props.unitEntries.some(
			(unitEntry) =>
				unitEntry.unit.owner !== GameContext.localObserverID &&
				!unitEntry.isCivilian &&
				unitEntry.relationship?.hostile,
		),
	);
	const hasPillagedConstructible = createMemo(() => props.constructibles.some((entry) => entry.damaged));
	const activeStorm = createMemo<RandomEventDefinition | null>(() => {
		const stormID = MapStorms.getActiveStormIDAtPlot(props.plotIndex);
		if (!stormID) {
			return null;
		}

		const stormInfo = MapStorms.getStorm(stormID);
		if (!stormInfo?.isActive) {
			return null;
		}

		return GameInfo.RandomEvents.lookup(stormInfo.type);
	});
	const plotEffectAlerts = createMemo(() => {
		const alerts: PlotAlertData[] = [];
		const activeStormEventClass = activeStorm()?.EventClass;

		for (const effect of props.plotEffects) {
			if (props.feature.volcano?.eruptionInfo?.isErupting && effect.plotEffectType === "PLOTEFFECT_IS_BURNING") {
				continue;
			}

			if (activeStormEventClass && effect.eventClass === activeStormEventClass) {
				continue;
			}

			const alert = getPlotEffectAlert(effect);
			if (alert) {
				pushUniqueAlert(alerts, alert);
			}
		}

		return alerts;
	});
	const activeStormAlert = createMemo<PlotAlertData | null>(() => {
		const storm = activeStorm();
		return storm ? getStormAlert(storm) : null;
	});
	const volcanoAlert = createMemo<PlotAlertData | null>(() => {
		const volcano = props.feature.volcano;
		if (!volcano?.active || !volcano.eruptionInfo?.isErupting) {
			return null;
		}

		const event = getVolcanoRandomEvent(props.feature.type, volcano.eruptionInfo);
		if (!event) {
			return null;
		}

		return {
			title: event.Name,
			tooltipText: getEventClassAlertTooltip("CLASS_VOLCANO"),
		};
	});

	const simpleAlerts = createMemo(() => {
		const alerts: PlotAlertData[] = [];

		const activeVolcanoAlert = volcanoAlert();
		if (activeVolcanoAlert) {
			pushUniqueAlert(alerts, activeVolcanoAlert);
		}

		for (const alert of plotEffectAlerts()) {
			if (alert.turns == null) {
				pushUniqueAlert(alerts, alert);
			}
		}

		const stormAlert = activeStormAlert();
		if (stormAlert && stormAlert.turns == null) {
			pushUniqueAlert(alerts, stormAlert);
		}

		if (hasPillagedConstructible()) {
			pushUniqueAlert(alerts, { title: "LOC_RESOURCE_PILLAGED" });
		}

		if (isOccupiedByEnemy()) {
			pushUniqueAlert(alerts, { title: "LOC_PLOT_TOOLTIP_ALERT_OCCUPIED" });
		}

		return alerts;
	});
	const timedAlerts = createMemo(() => {
		const alerts: PlotAlertData[] = [];

		for (const alert of plotEffectAlerts()) {
			if (alert.turns != null) {
				pushUniqueAlert(alerts, alert);
			}
		}

		return alerts;
	});
	const districtHealthAlert = createMemo<PlotDistrictHealthAlertData | null>(() => {
		const health: PlotDistrictHealthInfo | null = districtHealth();
		if (!health) {
			return null;
		}

		return {
			title: health.isUnderSiege ? "LOC_PLOT_TOOLTIP_UNDER_SIEGE" : "LOC_PLOT_TOOLTIP_DAMAGED_WALLS",
			currentHealth: health.currentHealth,
			maxHealth: health.maxHealth,
		};
	});
	const hasAlerts = createMemo(
		() => simpleAlerts().length > 0 || timedAlerts().length > 0 || districtHealthAlert() != null,
	);

	return (
		<Show when={hasAlerts()}>
			<>
				<Show when={simpleAlerts().length > 0}>
					<TicketSection
						name="PlotAlertSection"
						variant="negative"
					>
						<TicketRow icon={<PlotAlertIcon />}>
							<div class="flex items-center w-full">
								<div class="font-title text-sm uppercase text-secondary flex-1 flex flex-wrap items-center">
									<For each={simpleAlerts()}>
										{(alert, index) => (
											<>
												<Show when={index() > 0}>
													<span class="mx-1">,</span>
												</Show>
												<PlotAlertLabel
													alert={alert}
													class="font-title text-sm uppercase"
													keywordClass="inline-flex"
												/>
											</>
										)}
									</For>
								</div>
							</div>
						</TicketRow>
					</TicketSection>
				</Show>

				<For each={timedAlerts()}>
					{(alert) => (
						<TicketSection
							name="PlotTimedAlertSection"
							variant={alert.variant ?? "negative"}
						>
							<TicketRow
								icon={
									<PlotAlertIcon
										icon={alert.icon}
										iconSizeClass={alert.iconSizeClass}
									/>
								}
							>
								<div class="flex items-center w-full">
									<PlotAlertLabel
										alert={alert}
										class="font-title text-sm uppercase flex-1"
										keywordClass="flex-1"
									/>
									<PlotAlertTimer turns={alert.turns} />
								</div>
							</TicketRow>
						</TicketSection>
					)}
				</For>

				<Show when={districtHealthAlert()}>
					{(healthAlert) => (
						<TicketSection
							name="PlotDistrictHealthAlertSection"
							variant="negative"
						>
							<TicketRow icon={<PlotAlertIcon />}>
								<L10n.Stylize
									class="font-title text-sm text-accent-1"
									text={healthAlert().title}
								/>
								<div class="flex items-center mt-0\.5 font-body text-sm text-accent-3">
									<Icon
										class="size-5 mr-1"
										name="DAMAGED"
									/>
									<span>{`${healthAlert().currentHealth}/${healthAlert().maxHealth}`}</span>
								</div>
							</TicketRow>
						</TicketSection>
					)}
				</Show>
			</>
		</Show>
	);
};
